#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
const int MOD=65537;int modpow(int a,ll b){int r=1;for(;b;b>>=1,a=1LL*a*a%MOD)if(b&1)r=1LL*r*a%MOD;return r;}void ntt(vector<int>&a,bool inverse){int n=a.size();for(int i=1,j=0;i<n;i++){int bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)swap(a[i],a[j]);}for(int len=2;len<=n;len<<=1){int root=modpow(3,(MOD-1)/len);if(inverse)root=modpow(root,MOD-2);for(int i=0;i<n;i+=len){int w=1;for(int j=0;j<len/2;j++){int x=a[i+j],y=1LL*a[i+j+len/2]*w%MOD;int sum=x+y,diff=x-y;a[i+j]=sum>=MOD?sum-MOD:sum;a[i+j+len/2]=diff<0?diff+MOD:diff;w=1LL*w*root%MOD;}}}if(inverse){int inv=modpow(n,MOD-2);for(auto&x:a)x=1LL*x*inv%MOD;}}vector<int> convolution(vector<int>a,vector<int>b){int length=a.size()+b.size()-1;if(min(a.size(),b.size())<30){vector<int>c(length);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size();j++)c[i+j]=(c[i+j]+1LL*a[i]*b[j])%MOD;return c;}int n=1;while(n<length)n<<=1;a.resize(n);b.resize(n);ntt(a,false);ntt(b,false);for(int i=0;i<n;i++)a[i]=1LL*a[i]*b[i]%MOD;ntt(a,true);a.resize(length);return a;}int main(){ll n,m;cin>>n>>m;if(m==1){cout<<1<<'\n';return 0;}if(m>n){cout<<modpow(2,n)<<'\n';return 0;}if(m<=32766){vector<int>p(m+1),q(m+2);p[0]=1;p[m]=MOD-1;q[0]=1;q[1]=MOD-2;q[m+1]=1;while(n){auto qm=q;for(int i=1;i<(int)qm.size();i+=2)if(qm[i])qm[i]=MOD-qm[i];auto a=convolution(p,qm),b=convolution(q,qm);p.clear();q.clear();for(int i=n%2;i<(int)a.size();i+=2)p.push_back(a[i]);for(int i=0;i<(int)b.size();i+=2)q.push_back(b[i]);while(p.size()>1&&!p.back())p.pop_back();while(q.size()>1&&!q.back())q.pop_back();n>>=1;}cout<<1LL*p[0]*modpow(q[0],MOD-2)%MOD<<'\n';return 0;}vector<int>fact(MOD),inv(MOD);fact[0]=1;for(int i=1;i<MOD;i++)fact[i]=1LL*fact[i-1]*i%MOD;inv.back()=modpow(fact.back(),MOD-2);for(int i=MOD-1;i;i--)inv[i-1]=1LL*inv[i]*i%MOD;auto choose=[&](ll a,ll b){ll answer=1;while(a||b){int x=a%MOD,y=b%MOD;if(y>x)return 0LL;answer=answer*fact[x]%MOD*inv[y]%MOD*inv[x-y]%MOD;a/=MOD;b/=MOD;}return answer;};auto coefficient=[&](ll v){if(v<0)return 0LL;ll answer=0;for(ll j=0;j*(m+1)<=v;j++){ll term=choose(v-j*m,j)*modpow(2,(v-j*(m+1))%32)%MOD;if(j%2)answer-=term;else answer+=term;if(answer>=MOD)answer-=MOD;if(answer<0)answer+=MOD;}return answer;};cout<<(coefficient(n)-coefficient(n-m)+MOD)%MOD<<'\n';}
